using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Collections.ObjectModel;
namespace MRS;
internal static class Update039Tests
{
 internal static PacketObservation Grant(long control,long voice,int tg=4660)=>new(DateTimeOffset.UtcNow,"Synthetic control",false,control,null,"TSBK CRC valid","","","","Group voice grant","TG "+tg,null,"","P25 Phase I",true,SourceKey:"fixture",P25Identity:new(0x293,0xABCDE,0x123,1,2),P25Assignments:[new(tg,12345,0,new(0x1002,1,2,voice,voice-45000000,null,1,"received table"))]);
 internal static void Run(Action<bool,string> check)
 {
  string root=Path.Combine(AppContext.BaseDirectory,"tests-039",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var p=Grant(851012500,851025000);var catalog=new P25Catalog();catalog.Observe(p);var c=SiteChannelData.FromP25(catalog.Rows.Single().Value)!;check(!c.Draft().Name.Contains("TG")&&!c.Draft().Notes.Contains("4660"),"Channel drafts do not store current talkgroup in channel name or notes");var db=new FrequencyLibrary(Path.Combine(root,"channels.json"));var first=db.SaveSiteChannels([c]);check(first.Added==1&&db.Items.Count(i=>!i.IsFolder)==1,"Live site channel creates scoped folder hierarchy");var entry=db.Items.Single(i=>!i.IsFolder);db.Upsert(entry with{Name="My channel",Notes="Keep this"});db.SaveSiteChannels([c with{Seen=DateTimeOffset.UtcNow.AddSeconds(1)}]);entry=db.Items.Single(i=>!i.IsFolder);check(entry.Name=="My channel"&&entry.Notes=="Keep this"&&entry.UplinkHz==806025000,"Site updates preserve user names/notes and paired uplink");db.SaveSiteChannels([c with{Scope="other site",Folders=["P25","ABCDE-123","RFSS 1 - Site 3"]}]);check(db.Items.Count(i=>!i.IsFolder)==2,"Same frequency at different sites remains independently scoped");
  var neighbor=p with{P25Assignments=null,P25SiteAnnouncement=new(0x123,1,4,null,null,[new(new(0x1002,1,2,851025000,806025000,null,1,"received table"),0)]),Kind="Adjacent site status"};catalog=new();catalog.Observe(neighbor);var n=SiteChannelData.FromP25(catalog.Rows.Single().Value)!;check(n.Folders.Last().Contains("Site 4")&&!n.Identifiers.Contains("NAC 293")&&n.Evidence.StartsWith("Advertised"),"Neighbor channels belong to advertised target, not receiving site");
  var foreign=neighbor with{P25SiteAnnouncement=neighbor.P25SiteAnnouncement! with{SystemId=0x456}};catalog=new();catalog.Observe(foreign);var target=SiteChannelData.FromP25(catalog.Rows.Single().Value)!;check(target.Evidence.StartsWith("Provisional")&&!target.Identifiers.Contains("WACN ABCDE"),"Neighbor system change does not invent its WACN from receiving context");
  var dmr=DmrBits.Parse(DmrTests.Bits(Convert.FromHexString(TrunkTests.CapCall)),null)! with{Network=99,Site=7};var dc=SiteChannelData.FromDmr(new(dmr,new("t","fixture",false,461150000),DateTimeOffset.UtcNow))!;check(dc.Folders.Contains("Network 99")&&dc.Folders.Contains("Site 7")&&!dc.Draft().Signaling.Contains("12345")&&!dc.Draft().Notes.Contains("TG"),"DMR site save retains site/CC without transient talkgroup or radio");check(SiteChannelData.FromDmr(new(dmr with{LinkValid=false,DataType=3},new("t","fixture",false,461150000),DateTimeOffset.UtcNow))==null,"Failed control data cannot silently create a verified site entry");
  var m=new TrunkFollower();m.Start(new("test","Synthetic","P25",851012500,[]),DateTimeOffset.UtcNow);m.ObserveP25(p,DateTimeOffset.UtcNow);m.ObserveP25(p with{P25Assignments=[p.P25Assignments![0] with{TalkgroupId=4661,Channel=p.P25Assignments[0].Channel with{DownlinkHz=851050000}}]},DateTimeOffset.UtcNow);check(m.AvailableCalls(DateTimeOffset.UtcNow).Length==2,"Control grants expose two distinct calls for a voice receiver pool");m.Ignored.Add(4661);check(m.AvailableCalls(DateTimeOffset.UtcNow).Length==1,"Pool allocation honors ignored talkgroups");m.Skip(DateTimeOffset.UtcNow);check(m.AvailableCalls(DateTimeOffset.UtcNow).Length==0,"Pool allocation respects skip suppression");
  var wire=Convert.FromHexString("830601B9DA0004C02802AAFF");var o=TrunkSignaling.Enrich(new(1,3,1,null,null,false,false,"",""),wire);check(o is{SystemType:"Connect Plus",Source:113114,Destination:1216,GrantChannel:2,GrantSlot:2,Group:true,LinkValid:true},"Independent DSD-FME Connect Plus group grant vector decodes LCN/slot/TG/source");
  m=new(){RequireConfirmations=false};m.Start(new("con","Synthetic Con+","Connect Plus",461000000,[new(2,461150000,false)]),DateTimeOffset.UtcNow);m.ObserveDmr(o,461000000,DateTimeOffset.UtcNow);check(m.Active is{Hz:461150000,Slot:2,Talkgroup:1216},"Mapped Connect Plus grant selects its own protocol voice call");
  var scoped=new TrunkFollower{RequireConfirmations=false};scoped.Start(new("expected","Expected Con+","Connect Plus",461000000,[new(2,461150000,false)],99,7),DateTimeOffset.UtcNow);scoped.ObserveDmr(o,461000000,DateTimeOffset.UtcNow);check(scoped.Active==null,"Imported map waits for its configured network/site before following");scoped.ObserveDmr(o with{Network=100,Site=7},461000000,DateTimeOffset.UtcNow);check(!scoped.Running,"A different decoded network cannot use an imported site's map");
  wire=(byte[])wire.Clone();wire[9]=3;FixCrc(wire);o=TrunkSignaling.Enrich(new(1,3,1,null,null,false,false,"",""),wire);m.End(DateTimeOffset.UtcNow,"test");m.ObserveDmr(o,461000000,DateTimeOffset.UtcNow);check(m.Active==null,"Connect Plus private grants are not followed as group calls");
  wire=new byte[12];wire[0]=0xB1;wire[2]=0x12;wire[3]=0x38;wire[4]=0;wire[5]=1;wire[6]=2;wire[7]=0;wire[8]=3;wire[9]=4;FixCrc(wire);o=TrunkSignaling.Enrich(new(1,3,1,null,null,false,false,"",""),wire);check(o is{SystemType:"DMR Tier III",GrantChannel:0x123,GrantSlot:2,Destination:258,Source:772},"Tier III group grant extracts 12-bit physical channel and selected slot");m=new(){RequireConfirmations=false};m.Start(new("tier","Synthetic Tier III","DMR Tier III",461000000,[new(0x123,461200000,false)]),DateTimeOffset.UtcNow);m.ObserveDmr(o,461000000,DateTimeOffset.UtcNow);check(m.Active is{Hz:461200000,Slot:2,Talkgroup:258},"Tier III grant requires explicit protocol-specific carrier mapping");wire[6]^=1;o=TrunkSignaling.Enrich(new(1,3,1,null,null,false,false,"",""),wire);check(!o.LinkValid&&o.GrantChannel==null,"Corrupt Tier III payload never supplies an actionable grant");
  string map=Path.Combine(root,"DSDPlus.frequencies");File.WriteAllText(map,"; protocol, network, site, OTA, TX, RX\nCon+,99,7,1,461.150,461.150,0\nCon+,99,7,2,461.150,461.150,0\nCon+,99,7,3,0.0,0.0,0\n");var imported=SavedChannelImport.DsdFrequencies(map).Single();check(imported.Carriers is[{Lcn:1,Hz:461150000,Confirmed:false}]&&imported.Unresolved==1,"DSDPlus import preserves slot-pair mapping, unresolved count and unconfirmed status");File.AppendAllText(map,"Con+,99,7,2,462.150,462.150,0\n");bool conflict=false;try{SavedChannelImport.DsdFrequencies(map);}catch(IOException){conflict=true;}check(conflict,"Conflicting imported OTA pair is rejected without changing source");
  string p25=Path.Combine(root,"DSDPlus.P25data");File.WriteAllText(p25," Network: ABCDE.123\n Site: 1.2 NAC=293\n Channel 1-2: 851.025 VOICE\n");var imp=SavedChannelImport.P25Data(p25).Single();check(imp.Channel=="01-0002"&&imp.Hz==851025000&&imp.Evidence.StartsWith("Imported historical"),"P25 import retains channel ID as text and explicit historical provenance");
  check(MonitorOrder.Time(p)==p.ObservedUtc&&MonitorOrder.Time(new DataSummaryRow(p))==p.ObservedUtc,"Raw and grouped monitoring rows share full last-received timestamps");
  object[] owners=Enumerable.Range(0,5).Select(_=>new object()).ToArray();try{for(uint i=0;i<5;i++)check(ReceiverOwnership.Acquire(owners[i],i,"fixture-"+i,"test",out _),$"Five-device ownership accepts independent receiver {i+1}");check(!ReceiverOwnership.Acquire(new object(),0,"fixture-0","duplicate",out _),"Device ownership prevents opening a sixth workspace on an already claimed SDR");}finally{foreach(var owner in owners)ReceiverOwnership.Release(owner);}
 }
 private static void FixCrc(byte[] b){int c=TrunkSignaling.Crc16(b.AsSpan(0,10))^0xA5A5;b[10]=(byte)(c>>8);b[11]=(byte)c;}
}
